frontend/src/styles.css
import { registrationTimeline } from "./registration-timeline";
import { sumAmounts } from "./sum-amounts";
import {
  formatAmount,
  type MemberDeclaration,
  type MemberDetails,
} from "./entity-details";

// https://api.parliament.uk/regnal-years/parliament-periods/59
export const CURRENT_PARLIAMENT_START = "2024-07-09T00:00:00Z";

function earningsTotal(declarations: MemberDeclaration[]) {
  const entries = declarations.flatMap((declaration) => declaration.entries);
  return {
    amount: sumAmounts(
      entries.flatMap((entry) =>
        entry.currency === "GBP" && entry.amount !== null ? [entry.amount] : [],
      ),
    ),
    incomplete: entries.some(
      (entry) =>
        !entry.currency?.trim() ||
        (entry.currency === "GBP" && entry.amount === null),
    ),
  };
}

function isEarnings(name: string): boolean {
  const label = name.trim().replace(/\s+/gu, " ").toLowerCase();
  return (
    label === "employment" ||
    label === "employment and earnings" ||
    label === "employment and earnings - ad hoc payments" ||
    label === "employment and earnings - ongoing paid employment"
  );
}

export function formatPounds(amount: string | null): string {
  if (amount === null) return formatAmount(null);
  const unsigned = amount.replace(/^-/, "");
  const [whole, fraction = ""] = unsigned.split(".");
  return `${amount.startsWith("-") ? "−" : ""}£${formatAmount(`${whole}.${fraction.padEnd(2, "0")}`)}`;
}

export function summarizeMember(details: MemberDetails) {
  const pounds = details.summary.currencies.find(
    (group) => group.currency === "GBP",
  );
  const declarations = details.declarations.filter((declaration) =>
    isEarnings(declaration.categoryName),
  );
  const { months: earnings, undated } = registrationTimeline(declarations);
  return {
    total: pounds?.amount ?? null,
    firstRegisteredAt: details.summary.firstRegisteredAt,
    earningsTotals: {
      currentTerm: earningsTotal(
        declarations.filter(
          (declaration) =>
            declaration.registeredAt !== null &&
            Date.parse(declaration.registeredAt) >=
              Date.parse(CURRENT_PARLIAMENT_START),
        ),
      ),
      historical: earningsTotal(declarations),
    },
    categories: pounds?.categories ?? [],
    earnings,
    undated,
  };
}
test("member earnings distinguish this term and history with registration coverage", async ({
  backend,
  page,
}) => {
  await mockDetails(backend);
  await backend.route("**/api/members/1", (route) =>
    route.fulfill({
      json: {
        ...memberDetails,
        summary: {
          ...memberDetails.summary,
          first_registered_at: "2020-01-01T00:00:00Z",
        },
        declarations: [
          {
            ...memberDetails.declarations[0],
            category_name: "Employment",
            registered_at: "2024-07-09T00:00:00Z",
            entries: [
              {
                amount: "200",
                currency: "GBP",
                funder: null,
                payment_type: null,
              },
            ],
          },
          {
            ...memberDetails.declarations[0],
            category_name: "Employment",
            registered_at: "2023-01-01T00:00:00Z",
            entries: [
              {
                amount: "100",
                currency: "GBP",
                funder: null,
                payment_type: null,
              },
            ],
          },
          {
            ...memberDetails.declarations[0],
            category_name: "Employment",
            registered_at: null,
            entries: [
              {
                amount: "50",
                currency: "GBP",
                funder: null,
                payment_type: null,
              },
            ],
          },
          {
            ...memberDetails.declarations[0],
            category_name: "Gifts",
            registered_at: "2020-01-01T00:00:00Z",
            entries: [],
          },
        ],
      },
    }),
  );
  await page.goto("/members/1");
  await expect(page.locator(".member-total")).toHaveText([
    "£200.00",
    "£350.00",
  ]);
  await expect(page.locator(".member-identity")).toContainText(
    "Since 9 July 2024",
  );
  await expect(page.locator(".member-identity")).toContainText(
    "Earliest stored declaration across all categories: 1 January 2020",
  );
  await expect(page.locator(".member-identity")).toContainText(
    "excluded from this term",
  );
  if (process.env.EXPOSED_SCREENSHOT_DIR)
    await page.screenshot({
      path: `${process.env.EXPOSED_SCREENSHOT_DIR}/member-earnings-summary.png`,
      fullPage: true,
    });
  await page
    .getByRole("link", { name: "Declaration history", exact: true })
    .click();
  await expect(page.locator(".member-total")).toHaveCount(0);
  if (process.env.EXPOSED_SCREENSHOT_DIR)
    await page.screenshot({
      path: `${process.env.EXPOSED_SCREENSHOT_DIR}/member-earnings-history.png`,
      fullPage: true,
    });
});

test("empty member earnings show unavailable totals and no stored date", async ({
  backend,
  page,
}) => {
  await mockDetails(backend);
  await backend.route("**/api/members/1", (route) =>
    route.fulfill({
      json: {
        ...memberDetails,
        declarations: [],
        summary: {
          ...memberDetails.summary,
          currencies: [],
          first_registered_at: null,
          last_registered_at: null,
          entry_count: 0,
          unknown_currency_count: 0,
          undated_declaration_count: 0,
        },
      },
    }),
  );
  await page.goto("/members/1");
  await expect(page.locator(".member-total")).toHaveText([
    "Amount unavailable",
    "Amount unavailable",
  ]);
  await expect(page.locator(".member-identity")).toContainText(
    "No dated declarations stored.",
  );
});

test("earnings keep precise figures readable on narrow screens and missing amounts neutral", async ({
  backend,
  page,
}) => {
  await mockDetails(backend);
  let amount: string | null = "1234567890.12";
  await backend.route("**/api/members/1", (route) =>
    route.fulfill({
      json: {
        ...memberDetails,
        declarations: [
          {
            ...memberDetails.declarations[0],
            category_name: "Employment",
            entries: [
              { amount, currency: "GBP", funder: null, payment_type: null },
            ],
          },
        ],
      },
    }),
  );
  for (const width of [850, 801, 601, 390]) {
    await page.setViewportSize({ width, height: 900 });
    await page.goto("/members/1");
    await expect(page.locator(".member-total")).toHaveText([
      "£1,234,567,890.12",
      "£1,234,567,890.12",
    ]);
    await page.evaluate(() => document.fonts.ready);
    const figures = await page
      .locator(".member-total")
      .evaluateAll((elements) =>
        elements.map((element) => {
          const text = document.createRange();
          text.selectNodeContents(element);
          return {
            fits: element.scrollWidth <= element.clientWidth,
            lines: text.getClientRects().length,
            fontSize: parseFloat(getComputedStyle(element).fontSize),
          };
        }),
      );
    for (const figure of figures) {
      expect(figure.fits).toBe(true);
      expect(figure.lines).toBe(1);
      expect(figure.fontSize).toBeGreaterThanOrEqual(24);
    }
  }
  const knownStyle = await page
    .locator(".member-total")
    .first()
    .evaluate((element) => ({
      color: getComputedStyle(element).color,
      fontSize: parseFloat(getComputedStyle(element).fontSize),
